#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// INV-129 enforcement (generated by arbiter for ts-library-fixture): no tracked
// data/state files or compiled binaries in the git index. Mirrors the self-repo
// gate (scripts/check-no-tracked-artifacts.mjs). A committed *.sqlite trips
// neither gitleaks (no secret pattern) nor pii-scan (it skips binaries), so this
// is the load-bearing retroactive catch for already-tracked data/binary files.
//
// Configurable: edit BANNED_PATTERNS / ALLOWLISTED_* below to match your project.
// Exit codes per INV-53: 0=PASS, 1=FAIL, 2=ERROR.
import { execFileSync } from 'node:child_process'
import { openSync, readSync, closeSync } from 'node:fs'
import { resolve, extname } from 'node:path'

const GIT_CWD = process.env['ARBITER_HOOK_GIT_CWD'] ?? process.cwd()

// Glob-matched banned artifacts: build outputs + data/state files.
// Add project-specific artifact globs here (e.g. '*.jar', '*.wheel' if not in dist/).
const BANNED_PATTERNS = [
  '*.tgz',
  '*.tar.gz',
  '*.sqlite',
  '*.sqlite3',
  '*.db',
  '*.db-shm',
  '*.db-wal',
]

// Allowlist — intentional committed binaries this gate must NOT flag.
const ALLOWLISTED_EXTS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.ico',
  '.bmp',
  '.woff',
  '.woff2',
  '.ttf',
  '.otf',
  '.eot',
  '.wasm',
  '.pdf',
])
const ALLOWLISTED_PATH_PREFIXES = ['__tests__/fixtures/', 'tests/fixtures/', 'fixtures/', 'testdata/']

function isAllowlisted(file) {
  const ext = extname(file).toLowerCase()
  if (ALLOWLISTED_EXTS.has(ext)) return true
  const norm = file.replace(/\\/g, '/')
  return ALLOWLISTED_PATH_PREFIXES.some((p) => norm.startsWith(p) || norm.includes(`/${p}`))
}

// Magic-byte signatures (PRIMARY signal): ELF 7F454C46 | PE/MZ 4D5A |
// Mach-O FEEDFACE/FEEDFACF/CEFAEDFE/CFFAEDFE/CAFEBABE.
function readMagic(absPath) {
  let fd
  try {
    fd = openSync(absPath, 'r')
    const buf = Buffer.alloc(4)
    const n = readSync(fd, buf, 0, 4, 0)
    return buf.subarray(0, n)
  } catch {
    return Buffer.alloc(0)
  } finally {
    if (fd !== undefined) closeSync(fd)
  }
}

function isCompiledBinary(absPath) {
  const m = readMagic(absPath)
  if (m.length < 2) return false
  if (m[0] === 0x7f && m[1] === 0x45 && m[2] === 0x4c && m[3] === 0x46) return true
  if (m[0] === 0x4d && m[1] === 0x5a) return true
  if (m.length === 4) {
    const u32 = m.readUInt32BE(0)
    if (
      u32 === 0xfeedface ||
      u32 === 0xfeedfacf ||
      u32 === 0xcefaedfe ||
      u32 === 0xcffaedfe ||
      u32 === 0xcafebabe ||
      u32 === 0xbebafeca
    ) {
      return true
    }
  }
  return false
}

function lsFiles(args) {
  return execFileSync('git', ['ls-files', ...args], { cwd: GIT_CWD, encoding: 'utf-8' })
    .trim()
    .split('\n')
    .filter(Boolean)
}

let failures = 0
try {
  // Fail-closed: a non-git CWD is ERROR (exit 2), never a silent NO-DATA PASS.
  execFileSync('git', ['rev-parse', '--git-dir'], { cwd: GIT_CWD, stdio: 'pipe' })

  for (const pattern of BANNED_PATTERNS) {
    for (const f of lsFiles([pattern])) {
      if (isAllowlisted(f)) continue
      process.stderr.write(`check-no-tracked-artifacts: FAIL — tracked artifact: ${f}\n`)
      failures++
    }
  }

  const GLOB_EXTS = new Set(['.tgz', '.sqlite', '.sqlite3', '.db', '.db-shm', '.db-wal'])
  for (const f of lsFiles([])) {
    if (isAllowlisted(f)) continue
    const ext = extname(f).toLowerCase()
    if (GLOB_EXTS.has(ext) || f.endsWith('.tar.gz')) continue
    const abs = resolve(GIT_CWD, f)
    if (isCompiledBinary(abs)) {
      process.stderr.write(`check-no-tracked-artifacts: FAIL — tracked compiled binary: ${f}\n`)
      failures++
    }
  }
} catch (err) {
  process.stderr.write(
    `check-no-tracked-artifacts: ERROR: ${err instanceof Error ? err.message : String(err)}\n`,
  )
  process.exit(2)
}

if (failures > 0) {
  process.exit(1)
}
process.stdout.write('check-no-tracked-artifacts: OK\n')
process.exit(0)
